from pathlib import Path
p=Path(__file__).parent/'persona-ui/src/territories.jsx'
s=p.read_text(encoding='utf-8')
s=s.replace("const nf=new Intl", "Object.assign(titles,{gdp:'State GDP',gdp_share:'Share of national GDP',gdp_per_capita:'GDP per person',crop_share:'Crop production share',livestock_share:'Livestock share',trade_share:'Trade share',construction_share:'Construction share',cement_share:'Cement manufacturing share',oil_share:'Oil / gas share'});\nconst economyKeys=['gdp','gdp_share','gdp_per_capita','crop_share','livestock_share','trade_share','construction_share','cement_share','oil_share'];\nconst nf=new Intl")
s=s.replace("if(key==='mpi')", "if(key==='gdp')return '₦'+(v/1e12).toFixed(1)+'tn';if(key==='gdp_per_capita')return '₦'+(v/1e6).toFixed(1)+'m';if(key.endsWith('_share'))return v.toFixed(1)+'%';if(key==='mpi')",1)
anchor='function App(){'
component='''function Economy({state,area,sources,onSource,onCompare}){return <section className="ti-panel ti-economy" id="economy"><div className="ti-section-title"><div><p className="ti-eyebrow">ECONOMIC PROFILE · 2023 · STATE LEVEL</p><h2>What drives {state.name}’s economy?</h2></div><button onClick={()=>onCompare('gdp')}>Compare state GDP ↗</button></div>{area.level!=='state'&&<div className="ti-notice"><strong>Containing-state context only</strong><p>These figures describe {state.name}, not {area.name}. No GDP or income has been allocated to this {area.level}.</p></div>}<div className="ti-economy-cards">{['gdp','gdp_share','gdp_per_capita'].map(k=>state.metrics[k]?<Metric key={k} name={k} m={state.metrics[k]} sources={sources} onSource={onSource}/>:<article className="ti-metric ti-unavailable" key={k}><h3>{titles[k]}</h3><strong>Not available</strong><p>No numeric figure verified for this state in the loaded source. Not zero.</p></article>)}</div><p className="ti-economy-note"><strong>GDP per person is economic output, not personal income or average salary.</strong> Household per-capita income is not available. Published 2023 per-person figures are used directly; they are not calculated with the atlas’s 2020 population estimates.</p><div className="ti-section-title"><div><h3>Reported leading sectors</h3><p>Share of this state’s GDP · NBS / World Bank · 2023 · Published data</p></div></div><div className="ti-sector-list">{[...(state.economic_sectors||[])].sort((a,b)=>state.metrics[b.key].value-state.metrics[a.key].value).map(sector=>{const m=state.metrics[sector.key];return <div key={sector.key} className="ti-sector-row"><button className="ti-sector-bar" onClick={()=>onSource({metric:m,title:state.name+' · '+sector.name})} aria-label={sector.name+': '+m.value+'% — view source'}><span>{sector.name}<b>{m.value.toFixed(1)}% ↗</b></span><span className="ti-sector-track"><i style={{width:m.value+'%'}}/></span></button><button className="ti-sector-compare" onClick={()=>onCompare(sector.key)}>Compare states ↗</button></div>})}</div><Provenance m={{value:3,source:'state_sectors',year:2023,level:'state',classification:'published',unit:'reported sectors'}} sources={sources} onSource={onSource}/><p className="ti-muted">Only the three sectors reported in the source are shown. Bars need not total 100%. Unlisted activities are unknown, not zero. Crop production and livestock are parts of agriculture; neither is the total agriculture contribution.</p><details><summary>Economic coverage and comparison limits</summary><p>2023 GDP totals: 3 of 37 areas. National GDP shares: 6 of 37. GDP per person: 6 of 37. Three reported sector shares: all 37. Comparisons rank available observations only, not every Nigerian state. Figures are rounded in the original publication (October 2025). No LGA or constituency economic estimates, household-income figures, full sector decomposition or current-year forecasts are loaded.</p></details></section>}
'''
s=s.replace(anchor,component+anchor)
s=s.replace("['population','poverty','health','project_budget','projects','registry_households'];", "['population','poverty','health','project_budget','projects','registry_households',...economyKeys];")
s=s.replace("a.caveat||(!m?'No verified measure at this geography':'')", "[a.caveat,m?.qualification,!m?'No verified measure at this geography':''].filter(Boolean).join(' ')")
s=s.replace('<section className="ti-lower-grid">', '''<Economy state={state} area={area} sources={sources} onSource={setDetail} onCompare={key=>{setMode('administrative');setLevel('state');setSelected(state.id);setFilter('');setQ('');setMetric(key);document.querySelector('.ti-workbench')?.scrollIntoView({behavior:'smooth'})}}/>
<section className="ti-lower-grid">''')
s=s.replace('Rankings use point estimates;', '{economyKeys.includes(metric)&&<strong>Partial economic coverage: available observations only, not a national ranking. Unlisted sectors are unknown. </strong>}Rankings use point estimates;')
s=s.replace('<p>{s.note}</p><small>{s.license}</small><a className="ti-primary"', '<p>{m.qualification}</p><p>{s.note}</p><small>{s.license}</small><a className="ti-primary"')
s=s.replace('<div className="ti-evidence-key">','<div className="ti-economy-jump"><a href="#economy" onClick={()=>setLedger(false)}>Explore GDP, output per person & sector contributions ↓</a><span>2023 state-level evidence · partial GDP coverage</span></div><div className="ti-evidence-key">')
p.write_text(s,encoding='utf-8')
css=Path(__file__).parent/'persona-ui/src/territories.css'
css.write_text(css.read_text()+'''
.ti-economy{margin:28px 0;scroll-margin-top:24px;border-top:4px solid #b98b42}.ti-economy-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.ti-economy-note{padding:16px;background:#f4f0e6;border-radius:12px;line-height:1.65}.ti-sector-list{display:grid;gap:14px;margin:22px 0}.ti-sector-row{display:grid;grid-template-columns:1fr 150px;gap:24px;align-items:center}.ti-sector-bar{background:transparent;border:0;text-align:left;padding:8px 0}.ti-sector-bar>span:first-child{display:flex;justify-content:space-between;gap:20px;margin-bottom:10px;font-size:15px}.ti-sector-track{display:block;height:16px;background:#edf0e8;border-radius:5px;overflow:hidden}.ti-sector-track i{display:block;height:100%;background:#328265;transition:width .25s}.ti-sector-bar:hover .ti-sector-track i{background:#14523e}.ti-sector-compare{font-size:12px}.ti-economy details{border-top:1px solid #dce3da;padding-top:16px}.ti-economy summary{cursor:pointer;font-weight:600}.ti-economy-jump{display:flex;justify-content:space-between;gap:16px;padding:18px 0;border-top:1px solid #dce3da}.ti-economy-jump a{font-weight:600}.ti-economy-jump span{font-size:12px;color:#627568}@media(max-width:700px){.ti-economy-cards{grid-template-columns:1fr}.ti-sector-row{grid-template-columns:1fr;gap:0}.ti-sector-compare{justify-self:start}.ti-economy-jump{flex-direction:column}.ti-economy .ti-section-title{flex-wrap:wrap}}
''',encoding='utf-8')
